const tmzStories=[
 {title:'Harry Styles Considering Nationwide Tour After MSG Success',blurb:'The residency’s demand may turn into a broader U.S. run—an interesting lesson in testing before scaling.',image:'https://imagez.tmz.com/image/e1/4by3/2026/09/02/e19c24bd9f7e41bbb34117db638debb1_md.jpg',url:'https://www.tmz.com/2026/09/02/harry-styles-considering-nationwide-tour-after-msg-success/'},
 {title:'Celine Dion Sings With Fans Outside Paris Hotel',blurb:'A spontaneous fan moment shows how access and authenticity create an audience memory.',image:'https://imagez.tmz.com/image/9a/16by9/2026/09/01/9a22c841c7394aee89ef37cd19a07282_md.png',url:'https://www.tmz.com/2026/09/01/celine-dion-sings-with-fans-in-paris/'},
 {title:'Doja Cat Opens Up About Past Cocaine Struggle',blurb:'The artist speaks candidly about a difficult chapter and where she is now.',image:'https://imagez.tmz.com/image/19/16by9/2026/08/31/1945f445e7c54d8dbc4359c7c7b27978_md.png',url:'https://www.tmz.com/2026/08/31/doja-cat-says-she-once-struggled-with-cocaine/'},
 {title:'Rick Springfield Still Rocking Shirtless at 77',blurb:'The longtime performer made age and longevity the story during his Las Vegas show.',image:'https://imagez.tmz.com/image/9f/16by9/2026/08/31/9f14aac291db4571920e2e77fedbcd7a_md.png',url:'https://www.tmz.com/2026/08/31/rick-springfield-shirtless-at-vegas-show/'},
 {title:'Olivia Rodrigo and Stevie Nicks Help Raise $20 Million',blurb:'A cross-generational performance helped turn a music festival into a major fundraising moment.',image:'https://imagez.tmz.com/image/4b/4by3/2026/08/30/4b844a7580db473eb6aede209dfb3a2a_md.jpg',url:'https://www.tmz.com/2026/08/30/olivia-rodrigo-raises-millions-at-daisy-chain-fields/'}
];
const stageRows={
 'Needs Bert':[['Student Startup Breakdown: DormDrop','Record the approved 62-second master','Recorded'],['Best cities for Hispanic entrepreneurs','Four channel edits ready for review','Review 4']],
 'In production':[['Founder ad-testing lesson','Captions and visual overlays in edit','View progress'],['Why founders lose money on ads','Master cut awaiting color pass','View progress'],['First-customer myth','Four channel versions generating','View progress']],
 'Content Bank':[['Pricing myths founders believe','Approved · publish priority 96','Open asset'],['How to test before you build','Approved · publish priority 91','Open asset'],['Office Hours: first customers','Approved · publish priority 87','Open asset']],
 'Published':[['Why founders keep funding bad ads','482K impressions · 8.9% engagement','Analytics'],['Student Startup Breakdown: Recycle','9,481 saves and shares','Analytics'],['The first-customer myth','318K impressions · 7.8% engagement','Analytics']]
};
function closeDrawer(){document.querySelector('#drawer').classList.remove('open')}
function renderTmzBrief(){const d=new Date(),show=d.getHours()<8||(d.getHours()===8&&d.getMinutes()<30)||new URLSearchParams(location.search).get('morning')==='1',m=document.querySelector('#morningBrief');if(!show){m.classList.add('hidden');return}m.classList.remove('hidden');m.innerHTML=`<img class="tmz-brand" src="assets/TMZ_Logo.svg" alt="TMZ">${tmzStories.map((s,i)=>`<button class="tmz-item" data-tmz="${i}"><img src="${s.image}" alt=""><span><b>${s.title}</b><small>${s.blurb}</small></span></button>`).join('')}`;m.querySelectorAll('[data-tmz]').forEach(b=>b.onclick=()=>{const s=tmzStories[+b.dataset.tmz];modal(s.title,`<img class="drawer-image" src="${s.image}" alt=""><p>${s.blurb}</p><a class="source-link" href="${s.url}" target="_blank" rel="noopener">Read the story on TMZ.com ↗</a>`)})}
function confirmExternal(title,onYes){modal(title,`<div class="send-warning">This was drafted with AI assistance.</div><p>Did you read the original, recipient, and complete draft?</p><button class="btn light" data-cancel>Keep editing</button> <button class="btn orange" data-confirm>Yes, send it</button>`);document.querySelector('[data-cancel]').onclick=()=>document.querySelector('#modal').classList.add('hidden');document.querySelector('[data-confirm]').onclick=()=>{document.querySelector('#modal').classList.add('hidden');onYes()}}
function fourEditReview(){drawer('Review all four channel edits',`<p>One master, adapted automatically. Scroll through every version; approve individually or send the whole package back with one note.</p>${['Instagram Reel','TikTok','YouTube Short','LinkedIn video'].map((x,i)=>`<article class="review-cut"><div class="phone-frame"><span>▶</span><small>${x}<br>${[47,43,52,58][i]} sec</small></div><div><b>${x}</b><p>${i===3?'Professional opening and burned-in captions.':'Platform-native hook, captions, safe zones, and CTA.'}</p><button class="btn light" data-approve-one>Approve</button></div></article>`).join('')}<label><b>One note for Creative</b></label><div class="script-editor" contenteditable="true">Tell us what should change across one or all versions…</div><button class="btn light" data-voice>● Talk through changes</button> <button class="btn light" data-return-edits>Send revisions</button> <button class="btn orange" data-approve-all>Approve all to Content Bank</button>`)}
function socialReply(sensitive=false){drawer(sensitive?'Critical comment review':'Reply to founder',`<div class="comment-original"><small>ORIGINAL COMMENT · INSTAGRAM</small><p>${sensitive?'“This advice is completely misleading. Professors have no idea what real founders face.”':'“How did you get your first ten customers without spending a fortune?”'}</p></div><label><b>Draft reply</b></label><div class="script-editor" contenteditable="true">${sensitive?'Fair challenge. Classroom advice only matters when it survives contact with real customers. Here is the specific test I recommend—and the evidence behind it…':'Great question. Start with ten conversations, not ten ads. Ask each person what they tried before, then offer one narrow result you can deliver manually.'}</div><button class="btn light" data-voice>● Edit by voice</button> <button class="btn orange" data-reply-send>Send reply</button>`);document.querySelector('[data-reply-send]').onclick=()=>confirmExternal('Send this reply?',()=>{toast('Reply sent');if(sensitive)document.querySelector('#globalAlert').classList.add('hidden');closeDrawer()})}
function priorityDetail(i,node){const p=priorities[i];if(i===1)return fourEditReview();if(i===2)return socialReply(false);drawer(p.title,`<div class="story-visual"><span>${i===0?'STUDENT STARTUP BREAKDOWN':'MEDIA RESPONSE'}</span><b>${i===0?'DormDrop turns move-out waste into a logistics business':'Expert comment: young founders using AI'}</b></div><p>${p.meta}</p><div class="detail-box"><b>Why this is ranked here</b><p>${i===0?'The story is timely, the script is approved, and your phone recording is the only remaining input.':'The reporter deadline is tomorrow and the response is already drafted.'}</p></div><label><b>${i===0?'Approved script':'Draft statement'}</b></label><div class="script-editor" contenteditable="true">${i===0?'Every May, college students throw away perfectly useful furniture. DormDrop saw waste. More importantly, these founders saw a logistics problem…':'Student founders are not replacing judgment with AI. The strongest ones use it to shorten the distance between an assumption and a real customer test…'}</div><button class="btn light" data-voice>● Edit by voice</button> <button class="btn orange" data-recorded>${i===0?'✓ Recorded on my phone':'Open email draft'}</button>`);document.querySelector('[data-recorded]').onclick=()=>{if(i===0&&node){node.remove();toast('Recording moved to Production');closeDrawer()}else opportunityDetail('Founder education reporter')}}
function publishedDetail(title){drawer(title,`<div class="analytics-score"><b>Strong performer</b><span>Top 12% this quarter</span></div><p><b>Instagram</b> 8.9% engagement · 4,821 saves</p><p><b>TikTok</b> 12.4% engagement · 318K views</p><p><b>YouTube</b> 61% average viewed</p><p><b>LinkedIn</b> 7.1% engagement · 936 follows</p><div class="detail-box"><b>Recommended next move</b><p>Build a three-part follow-up while this question is still generating qualified profile visits.</p></div><button class="btn orange" data-toast="Follow-up series added to Ideas">Make more like this</button>`)}
function renderStage(target,label){const rows=stageRows[label]||[];target.innerHTML=rows.map((x,i)=>`<button class="content-row" data-stage-row="${label}" data-stage-index="${i}"><span class="status-dot"></span><span><b>${x[0]}</b><small>${x[1]}</small></span><span class="pill">${label}</span><em>${x[2]} →</em></button>`).join('');target.querySelectorAll('[data-stage-row]').forEach(b=>b.onclick=()=>{if(label==='Needs Bert'&&+b.dataset.stageIndex===1)return fourEditReview();if(label==='Published')return publishedDetail(rows[+b.dataset.stageIndex][0]);drawer(rows[+b.dataset.stageIndex][0],`<p>${rows[+b.dataset.stageIndex][1]}</p><div class="detail-box"><b>Current stage</b><p>${label}. This is the only production record; dashboards are filtered views of it.</p></div><button class="btn orange" data-toast="Item opened">${rows[+b.dataset.stageIndex][2]}</button>`)})}
function opportunityDetail(title='Founder education reporter'){drawer(title,`<div class="opportunity-proof"><div><small>REACH</small><b>850K+</b></div><div><small>FIT</small><b>94/100</b></div><div><small>EFFORT</small><b>2 min</b></div></div><p><b>Source:</b> Verified media request and public professional profile.</p><p><b>Why it fits:</b> Your applied entrepreneurship and founder-advising experience directly match the request.</p><div class="detail-box"><b>Recommended owner</b><p>BOS prepares research and draft. Bert reviews and sends. No paid service or Claude Chrome required.</p></div><p><b>From:</b> Connected Entrepreneurship Professor Gmail</p><label><b>Subject</b></label><input class="edit-input" value="Practical perspective on young founders using AI"><label><b>Email</b></label><div class="script-editor" contenteditable="true">Hi Alex,\n\nI saw your request for perspectives on young founders using AI. One pattern I see repeatedly is…\n\nWith gratitude,\nBert</div><button class="btn light" data-voice>● Edit by voice</button> <button class="btn light" data-toast="Draft saved">Save</button> <button class="btn orange" data-send-email>Send email</button>`);document.querySelector('[data-send-email]').onclick=()=>confirmExternal('Send this email?',()=>{toast('Email sent after confirmation');closeDrawer()})}
function decisionDrawer(title){drawer(title,`<p><b>Signal:</b> This question is recurring across multiple channels and has enough evidence to warrant a decision.</p><div class="detail-box"><b>Recommended</b><p>Act now: Creative can build the brief and only return when your recording is needed.</p></div><label><b>Your direction</b></label><div class="script-editor" contenteditable="true">Add context or tell the team how you want to approach it…</div><button class="btn light" data-voice>● Talk</button><div class="decision-actions"><button class="btn orange" data-decision="Acting now">Act now</button><button class="btn light" data-decision="Saved to think about">Think about it</button><button class="btn danger" data-decision="Killed">Kill</button></div>`);document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>{toast(b.dataset.decision);closeDrawer()})}
function meetingPrep(){drawer('Prepare me: ENT 330',`<div class="audio-brief">▶ Play 30-second brief</div><p><b>Purpose:</b> Lead today’s Applied Innovation Lab.</p><section class="people-prep"><div class="card-head"><div><span class="eyebrow">People</span><h3>Talk to them about</h3></div><span class="pill">3 people</span></div>${[['Maya Chen','Ask what happened in last week’s customer interviews.'],['Jordan Ellis','Decide whether the team should narrow the first test.'],['Alex Rivera','Follow up on the alumni introduction.']].map((x,i)=>`<div class="person-row"><button class="talk-check" aria-label="Mark discussed">✓</button><img src="https://i.pravatar.cc/80?img=${i+12}" alt=""><span><b>${x[0]}</b><small>${x[1]}</small></span><button class="text-btn" data-person-note>Note</button></div>`).join('')}</section><label><b>Meeting note</b></label><div class="script-editor" contenteditable="true">Talk or type what happened. The system will identify commitments, update projects, and create follow-ups.</div><button class="btn light" data-voice>● Record note</button> <button class="btn orange" data-process-note>Process note + move work forward</button>`);document.querySelectorAll('.talk-check').forEach(b=>b.onclick=()=>{b.closest('.person-row').classList.toggle('done');toast(b.closest('.person-row').classList.contains('done')?'Marked discussed':'Reopened')});document.querySelectorAll('[data-person-note]').forEach(b=>b.onclick=()=>{b.closest('.person-row').classList.add('has-note');b.textContent='Noted ✓';toast('Person note captured')});document.querySelector('[data-process-note]').onclick=()=>{toast('Projects updated and follow-ups created');closeDrawer()}}
function addOpportunity(){drawer('Add an opportunity',`<button class="record-opportunity" data-voice><span>●</span><b>Describe it</b><small>Record what you noticed</small></button><div class="drop-zone"><b>Drop a file here</b><small>Screenshot, PDF, image, or brief</small></div><label><b>Or paste a link</b></label><input class="edit-input" placeholder="https://…"><label><b>Anything else?</b></label><div class="script-editor" contenteditable="true">Add context…</div><button class="btn orange" data-analyze-opportunity>Save + analyze</button>`);document.querySelector('[data-analyze-opportunity]').onclick=()=>{closeDrawer();toast('Opportunity saved · analysis underway')}}
function improvePage(){const page=location.hash.slice(1)||'today';document.querySelectorAll('[data-priority]').forEach(b=>b.onclick=()=>priorityDetail(+b.dataset.priority,b));document.querySelectorAll('[data-opportunity]').forEach(b=>b.onclick=()=>opportunityDetail(b.querySelector('b')?.textContent));document.querySelectorAll('[data-toast]').forEach(b=>{if(!b.onclick)b.onclick=()=>toast(b.dataset.toast)});
 const pageTabs=[...document.querySelectorAll('section.card .tabs')].find(t=>[...t.children].some(b=>b.textContent.includes('In production')));if(pageTabs){const target=pageTabs.closest('section').querySelector('.content-table')||pageTabs.closest('section');[...pageTabs.children].forEach(b=>b.onclick=()=>{[...pageTabs.children].forEach(x=>x.classList.remove('active'));b.classList.add('active');const label=b.textContent.split('·')[0].trim();if(target.classList.contains('content-table'))renderStage(target,label);else{target.querySelectorAll('.action-row').forEach(x=>x.remove());target.insertAdjacentHTML('beforeend',stageRows[label].map(x=>actionRow('•',x[0],x[1],x[2])).join(''));improvePage()}})}
 if(page==='content'){const head=document.querySelector('.page-head .head-buttons');if(head)head.innerHTML='<button class="btn orange" data-unified-record>● Record content</button>';document.querySelector('[data-unified-record]')?.addEventListener('click',()=>drawer('Record content',`<p>Choose a guided script or talk freely. The system will create one master and adapt it automatically.</p><button class="btn orange" data-toast="Guided recording opened">Use prepared script</button> <button class="btn light" data-free-record>Talk freely</button>`))}
 if(page==='radar'){const cards=[...document.querySelectorAll('#app>section.card')];if(cards.length>1&&!cards[0].textContent.includes('Radar actions')){const actions=cards.at(-1);cards[0].before(actions);actions.querySelector('.quick-opps').classList.add('three');actions.querySelector('.quick-opps').insertAdjacentHTML('beforeend','<button data-opportunity="expert"><b>Pitch a reporter</b><small>3 verified contacts with current beats</small><em>Draft →</em></button><button data-toast="Fast-moving stories filtered"><b>Record while hot</b><small>4 stories likely to decay within 24 hours</small><em>Review →</em></button>');actions.querySelector('[data-toast*="Expert"]')?.addEventListener('click',()=>opportunityDetail('Offer expert comment'));actions.querySelectorAll('[data-opportunity]').forEach(b=>b.onclick=()=>opportunityDetail('Pitch a reporter'))}}
 if(page==='audience'){const signalCard=[...document.querySelectorAll('.card')].find(c=>c.textContent.includes('Questions + signals'));if(signalCard){if(signalCard.querySelectorAll('.signal-row').length<3)signalCard.insertAdjacentHTML('beforeend','<div class="signal-row"><b>“Can I start before choosing a major?”</b><small>11 questions from high-school and first-year audiences</small><button class="btn light">Decide</button></div>');signalCard.querySelectorAll('.signal-row button').forEach(b=>{b.textContent='Decide';b.onclick=()=>decisionDrawer(b.closest('.signal-row').querySelector('b').textContent)})}}
 if(page==='partnerships'){const add=[...document.querySelectorAll('.page-head button')].find(b=>b.textContent.includes('Add opportunity'));if(add){add.removeAttribute('data-toast');add.onclick=addOpportunity}const describe=[...document.querySelectorAll('.page-head button')].find(b=>b.textContent.includes('Describe'));if(describe)describe.innerHTML='◉ Describe an opportunity'}
 const inbox=[...document.querySelectorAll('.card')].find(c=>c.textContent.includes('Replies needing approval'));if(inbox){const bs=inbox.querySelectorAll('.action-row button');if(bs[0])bs[0].onclick=()=>socialReply(true);if(bs[1])bs[1].onclick=()=>socialReply(false)}
 document.querySelectorAll('[data-voice]').forEach(b=>b.onclick=()=>toast('Listening… talk naturally'));document.querySelectorAll('[data-approve-one]').forEach(b=>b.onclick=()=>{b.textContent='Approved ✓';b.classList.add('complete-btn')});document.querySelector('[data-approve-all]')?.addEventListener('click',()=>{toast('All four approved to Content Bank');closeDrawer()});document.querySelector('[data-return-edits]')?.addEventListener('click',()=>{toast('Revision notes sent to Creative');closeDrawer()})}
window.addEventListener('hashchange',()=>setTimeout(improvePage,0));setTimeout(()=>{renderTmzBrief();improvePage();document.querySelector('#prepareMe').onclick=meetingPrep;document.querySelector('#countdownRing').onclick=meetingPrep;document.querySelector('#openAlert').onclick=()=>socialReply(true)},0);
